#include "speex/speex_echo.h"
#include "speex/speex_preprocess.h"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define NN 128
#define TAIL 1024

int main(int argc, char **argv)
{
   FILE *fm = fopen(argv[1], "rb");
   FILE *ff = fopen(argv[2], "rb");
   short mic[NN], far[NN], out[NN];
   SpeexEchoState *st = speex_echo_state_init(NN, TAIL);
   SpeexPreprocessState *pre = speex_preprocess_state_init(NN, 8000);
   int rate = 8000, frame = 0;
   double mic_e = 0, out_e = 0, pre_e = 0;
   speex_echo_ctl(st, SPEEX_ECHO_SET_SAMPLING_RATE, &rate);
   if (argc > 3)
      speex_preprocess_ctl(pre, SPEEX_PREPROCESS_SET_ECHO_STATE, st);
   while (fread(mic, 2, NN, fm) == NN && fread(far, 2, NN, ff) == NN)
   {
      speex_echo_cancellation(st, mic, far, out);
      if (argc > 3)
         speex_preprocess_run(pre, out);
      /* far-only scoring region: frames 60..199 (before first DT at 200) */
      if (frame >= 60 && frame < 200)
      {
         int i;
         for (i = 0; i < NN; i++) { mic_e += (double)mic[i]*mic[i]; out_e += (double)out[i]*out[i]; }
      }
      frame++;
   }
   (void)pre_e;
   printf("baseline ERLE frames 60-199: %.2f dB over %d frames\n",
          10*log10((mic_e+1)/(out_e+1)), frame);
   return 0;
}

