def isdt(f): return (200<=f<=299) or (380<=f<=449)
# sliding: flagged if within last W frames at least K satisfy condition
def sim(cond,W,K,hold):
    flags={}
    hist=[]
    for r in rows:
        hist.append(1 if cond(r) else 0)
        if len(hist)>W: hist.pop(0)
        flags[int(r['f'])]= 1 if sum(hist)>=K else 0
    # apply hold: once flagged, stay while any recent... simple: smooth with release hold
    out={}; on=0
    for r in rows:
        f=int(r['f'])
        if flags[f]: on=hold
        elif on>0: on-=1
        out[f]= 1 if on>0 else 0
    fr=[f for f in out if not isdt(f)]; dt=[f for f in out if isdt(f)]
    fa=sum(out[f] for f in fr)/len(fr); hit=sum(out[f] for f in dt)/len(dt)
    return fa,hit
