#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
#define RATE 8000
#define FRAME 128
#define TAIL 1024
#define DURATION 8
#define TOTAL (RATE*DURATION)
#define DT1S 200
#define DT1E 299
#define DT2S 380
#define DT2E 449

static unsigned int rs = 0x12345678;
static float frand(void){ unsigned x=rs; x^=x<<13; x^=x>>17; x^=x<<5; rs=x;
  return ((x>>8)/(float)(1u<<24))*2.f-1.f; }

/* speech-like: band-limited colored noise through a one-pole formant,
   gated by a slow talk envelope; seed shifts the talk pattern phase */
static float lp = 0.f;
static float speech_sample(int n, int seed)
{
  float t = n/(float)RATE;
  float phase = fmodf(t + seed*1.37f, 1.8f);
  float env;
  if (phase < .08f) env = phase/.08f;
  else if (phase < 1.6f) env = 1.f;
  else if (phase < 1.7f) env = (1.7f-phase)/.1f;
  else env = 0.f;
  float white = frand();
  /* two-pole-ish colored noise, pole radius gives a speech-like spectrum */
  lp = .85f*lp + .15f*white;
  float f0 = 120.f + 20.f*sinf(.5f*t+seed);
  float tone = .35f*sinf(2*M_PI*f0*t + seed) + .2f*sinf(2*M_PI*2*f0*t);
  return .55f*env*(.7f*lp + tone);
}
static int near_active(int f){ return (f>=DT1S&&f<=DT1E)||(f>=DT2S&&f<=DT2E); }

int main(int argc,char**argv)
{
  const char* dir = argc>1?argv[1]:".";
  char p[1024]; FILE*ff,*fn,*fm,*fc;
  float *far=calloc(TOTAL,4),*near=calloc(TOTAL,4),*echo=calloc(TOTAL,4),ir[TAIL];
  short*o=malloc(TOTAL*2); int n,k,frames=TOTAL/FRAME;
  for(n=0;n<TOTAL;n++) far[n]=speech_sample(n,1);
  for(n=0;n<TOTAL;n++) if(near_active(n/FRAME)) near[n]=1.5f*speech_sample(n,7);
  for(k=0;k<TAIL;k++) ir[k]=0.f;
  ir[40]=.7f; ir[95]=.32f; ir[180]=.2f; ir[300]=.12f; ir[520]=.07f;
